const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([140.878144, 27.245974]);
  const buffer = point.buffer(2000); // 2 km radius
  const targetDate = '2013-12-08';
  const dateStart = '2013-12-01';
  const dateEnd = '2013-12-15';

  console.log('Analyzing location: (27.245974, 140.878144)');
  console.log('Date: December 8, 2013, Buffer: 2 km');

  // 2. Data Acquisition - Try Landsat 8 first, then Landsat 7
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(buffer)
    .filterDate(dateStart, dateEnd)
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  let size = await collection.size().getInfo();
  console.log('Landsat 8 images found:', size);

  if (size === 0) {
    // Try Landsat 7
    collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(dateStart, dateEnd)
      .filter(ee.Filter.lt('CLOUD_COVER', 20));

    size = await collection.size().getInfo();
    console.log('Landsat 7 images found:', size);

    if (size === 0) {
      console.log('No images found in date range.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Get best image (least cloudy, closest to target date)
  const image = collection.sort('CLOUD_COVER').first();

  // For Landsat 8: NIR=SR_B5, SWIR1=SR_B6
  // For Landsat 7: NIR=SR_B4, SWIR1=SR_B5
  const nir = image.select('SR_B5').multiply(0.0000275).add(-0.2);
  const swir = image.select('SR_B6').multiply(0.0000275).add(-0.2);

  // Calculate NDWI (water index: (NIR - SWIR) / (NIR + SWIR))
  const ndwi = nir.subtract(swir).divide(nir.add(swir)).rename('ndwi');

  // Classify: water (NDWI > 0), land (NDWI <= 0)
  const land = ndwi.lt(0).selfMask().clip(buffer);

  // 4. Check for valid pixels
  const pixelCount = await land.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  }).get('ndwi').getInfo();

  console.log('Valid land pixels:', pixelCount);

  if (pixelCount === 0 || pixelCount === null) {
    console.log('No land pixels detected in buffer.');
    console.log('<answer>B</answer>');
    return;
  }

  // 5. Identify connected land masses (islands)
  const connected = land.connectedPixelCount(256, false);
  const islands = connected.gt(10); // Minimum 10 pixels to be considered an island

  // Label each distinct island
  const labeled = islands.connectedComponents({
    connectedness: ee.Kernel.square(1),
    maxSize: 256
  });

  // 6. Count distinct islands
  const islandCount = await labeled.select('labels').reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  }).get('labels').getInfo();

  console.log('Number of distinct islands found:', islandCount);

  // 7. Final Answer
  if (islandCount === null || islandCount === undefined) {
    console.log('Island counting failed.');
    console.log('<answer>C3</answer>');
  } else if (islandCount === 2) {
    console.log('Exactly 2 isolated islands detected.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Not exactly 2 islands.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
